// Identify duplicate rows by MCS Cert Number, keeping the FIRST occurrence.
// Emits merged, descending deleteDimension ranges so indices never shift.
try {
  var valsRes = $input.first().json;
  var rows = valsRes.values || [];
  if (rows.length < 2) { return [{ json: { _error: 'Sheet has no data rows' } }]; }

  var metaRes = $('📐 Get Sheet Metadata').first().json;
  var sheets = (metaRes && metaRes.sheets) ? metaRes.sheets : [];
  var sheetId = null;
  for (var s = 0; s < sheets.length; s++) {
    var p = sheets[s].properties || {};
    if (p.title === 'Outreach CRM') { sheetId = p.sheetId; break; }
  }
  if (sheetId === null) { return [{ json: { _error: 'Tab "Outreach CRM" not found' } }]; }

  var header = rows[0];
  var iCert = header.indexOf('MCS Cert Number');
  var iName = header.indexOf('Company Name');
  var iPhone = header.indexOf('Phone');
  if (iCert === -1) { return [{ json: { _error: 'Header "MCS Cert Number" not found' } }]; }

  var seen = {};
  var dupRows = [];      // 0-based SHEET row indices (header = 0)
  var noCert = 0, kept = 0;
  var examples = [];

  for (var r = 1; r < rows.length; r++) {
    var row = rows[r] || [];
    var cert = (row[iCert] === undefined) ? '' : String(row[iCert]).trim();
    if (!cert) { noCert++; kept++; continue; }   // never delete a row we can't key
    if (seen[cert]) {
      dupRows.push(r);
      if (examples.length < 5) {
        examples.push({ sheetRow: r + 1, name: row[iName] || '', cert: cert, phone: row[iPhone] || '' });
      }
    } else {
      seen[cert] = true;
      kept++;
    }
  }

  // Merge consecutive indices into ranges, then sort DESCENDING.
  dupRows.sort(function(a, b) { return a - b; });
  var ranges = [];
  for (var d = 0; d < dupRows.length; d++) {
    var start = dupRows[d];
    var end = start;
    while (d + 1 < dupRows.length && dupRows[d + 1] === end + 1) { d++; end = dupRows[d]; }
    ranges.push({ startIndex: start, endIndex: end + 1 });
  }
  ranges.sort(function(a, b) { return b.startIndex - a.startIndex; });

  var requests = [];
  for (var q = 0; q < ranges.length; q++) {
    requests.push({ deleteDimension: { range: {
      sheetId: sheetId, dimension: 'ROWS',
      startIndex: ranges[q].startIndex, endIndex: ranges[q].endIndex
    }}});
  }

  var body = $('📥 Run').first().json.body || {};
  var apply = body.apply === true;

  return [{ json: {
    sheetId: sheetId,
    dataRowsBefore: rows.length - 1,
    uniqueCerts: Object.keys(seen).length,
    rowsWithoutCert: noCert,
    duplicatesFound: dupRows.length,
    expectedRowsAfter: kept,
    deleteRangeCount: ranges.length,
    firstRanges: ranges.slice(0, 5),
    examples: examples,
    apply: apply,
    requests: apply ? requests : []
  }}];
} catch (e) {
  return [{ json: { _error: 'Find Duplicates failed: ' + e.message } }];
}

try {
  var plan = $('🧮 Find Duplicates').first().json;
  var res = $input.first().json || {};
  var replies = (res.replies || []).length;
  return [{ json: {
    mode: plan.apply ? 'APPLIED' : 'DRY RUN (post {"apply":true} to delete)',
    dataRowsBefore: plan.dataRowsBefore,
    duplicatesFound: plan.duplicatesFound,
    uniqueCerts: plan.uniqueCerts,
    rowsWithoutCert: plan.rowsWithoutCert,
    expectedRowsAfter: plan.expectedRowsAfter,
    deleteRangesSent: plan.apply ? plan.deleteRangeCount : 0,
    apiRepliesReceived: replies,
    firstRanges: plan.firstRanges,
    duplicateExamples: plan.examples,
    apiError: res.error ? res.error : null
  }}];
} catch (e) {
  return [{ json: { _error: 'Summary failed: ' + e.message } }];
}
